const BASE_TYPE_ALLOWANCE = 3;

const SPHINX_BASE_POINTS = 1;

const BASE_BONUS = 1;

const POINTS_PER_EXTRA_TYPE = 2;

export const scoreArmy = (army: Card[]): number => {
  if (!hasSphinx(army)) return 0;
  const nonSphinxTypes = countDistinctMonsterTypes(army) - 1;
  const extraTypes = Math.max(nonSphinxTypes - BASE_TYPE_ALLOWANCE, 0);
  const bonus = extraTypes > 0 ? POINTS_PER_EXTRA_TYPE * extraTypes : BASE_BONUS;
  return SPHINX_BASE_POINTS + bonus;
};

